// @ts-expect-error -- .open-next/worker.js is generated by `opennextjs-cloudflare build` and has no types.
import openNext from "./.open-next/worker.js";
import { edgeCacheHeaders, isEdgeCacheableRequest, renderState } from "./src/lib/edge-cache";

type Handler = { fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> };
const next = openNext as Handler;

// Wraps the OpenNext worker so Workers Cache (wrangler.jsonc "cache") can store anonymous public pages.
const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> {
    if (!isEdgeCacheableRequest(request)) return next.fetch(request, env, ctx);
    const state = { degraded: false };
    return renderState.run(state, async () => {
      const response = await next.fetch(request, env, ctx);
      // Read the whole body first: rendering may still be fetching data after the headers exist,
      // and the degraded flag is only final once the page is complete.
      const body = await response.arrayBuffer();
      return new Response(request.method === "HEAD" ? null : body, {
        status: response.status,
        statusText: response.statusText,
        headers: edgeCacheHeaders(response, state.degraded) ?? response.headers,
      });
    });
  },
};

export default worker;
